import unittest
from slug import slugify

class TestSlugify(unittest.TestCase):
    def test_normal_string(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_mixed_case_and_space(self):
        self.assertEqual(slugify("  Python Is Fun  "), "python-is-fun")

    def test_punctuation_sequence(self):
        self.assertEqual(slugify("What--is-this?!"), "what-is-this")

    def test_non_ascii(self):
        # "世界" are two non-ASCII characters, each replaced by a hyphen, 
        # then collapsed into one.
        self.assertEqual(slugify("Hello, 世界!"), "hello-world")

    def test_empty_and_punctuation_only(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify("!!!"), "")
        self.assertEqual(slugify("   "), "")

    def test_numbers(self):
        self.assertEqual(slugify("Year 2024"), "year-2024")

    def test_complex_mixed(self):
        self.assertEqual(slugify("123...456!!!"), "123-456")
        self.assertEqual(slugify("---leading and trailing---"), "leading-and-trailing")

if __name__ == "__main__":
    unittest.main()

